package br.com.admeclesial.domain.matrimonio;
import br.com.admeclesial.domain.sacramento.Sacramento;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="matrimonio",schema="adm_eclesial") public class Matrimonio { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="processo_matrimonial_id",unique=true) ProcessoMatrimonial processo; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="celebracao_matrimonial_id",unique=true) CelebracaoMatrimonial celebracao; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="sacramento_id",unique=true) Sacramento sacramento; @Column(name="data_registro",nullable=false) LocalDate dataRegistro; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID(); if(dataRegistro==null)dataRegistro=LocalDate.now();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public ProcessoMatrimonial getProcesso(){return processo;} public CelebracaoMatrimonial getCelebracao(){return celebracao;} public Sacramento getSacramento(){return sacramento;} public LocalDate getDataRegistro(){return dataRegistro;} public String getObservacao(){return observacao;} public void setProcesso(ProcessoMatrimonial v){processo=v;} public void setCelebracao(CelebracaoMatrimonial v){celebracao=v;} public void setSacramento(Sacramento v){sacramento=v;} public void setDataRegistro(LocalDate v){dataRegistro=v;} public void setObservacao(String v){observacao=v;} }